/// <summary>
/// AVA/WEN/2024/10/08    AVA_011503_CreateProject
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[    SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormControlEventHandler(formControlStr(AVAPTMToolTableListPage, AVAProductionProject), FormControlEventType::Clicked)]
public static void AVAProductionProject_OnClicked(FormControl sender, FormControlEventArgs e)
{
    KCS_PTMToolTable toolTable = sender.formRun().dataSource(formDataSourceStr(AVAPTMToolTableListPage,KCS_PTMToolTable)).cursor();
    if (toolTable.KCS_ProducerUK != curExt())
    {
        appl.setDefaultCompany(toolTable.KCS_ProducerUK);
        SysSecurity::reload(false);
        SysDataAreaSelectExtension::fireDataAreaChanged();
    }
}

