/// <summary>
///  AVA/WEN/2025/05/14     AVA_013002
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormControlEventHandler(formControlStr(AVAPTMToolTableListPage, AVAWrkCtrDateCalendar), FormControlEventType::Clicked)]
public static void AVAWrkCtrDateCalendar_OnClicked(FormControl sender, FormControlEventArgs e)
{
    KCS_PTMToolTable toolTable = sender.formRun().dataSource(formDataSourceStr(AVAPTMToolTableListPage,KCS_PTMToolTable)).cursor();
    WrkCtrTable wrkCtrTable = wrkCtrTable::find(toolTable.ToolId);

    Args args = new Args();
    args.record(wrkCtrTable);
    MenuFunction menuFunction = new MenuFunction(menuItemDisplayStr(WrkCtrDateCalendar), MenuItemType::Display);
    menuFunction.run(args);

}
